  function clamp01(x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
  function sm(x) { x = clamp01(x); return x * x * (3 - 2 * x); }
  function kfNum(arr, m, def) {
    if (!arr) return def;
    if (m <= arr[0][0]) return arr[0][1];
    for (var i = 1; i < arr.length; i++) if (m <= arr[i][0]) { var a = arr[i - 1], b = arr[i]; return a[1] + (b[1] - a[1]) * sm((m - a[0]) / (b[0] - a[0])); }
    return arr[arr.length - 1][1];
  }
  function kfVec(arr, m, out) {
    if (!arr) return out.set(0, 0, 0);
    if (m <= arr[0][0]) return out.fromArray(arr[0][1]);
    for (var i = 1; i < arr.length; i++) if (m <= arr[i][0]) {
      var a = arr[i - 1], b = arr[i], k = sm((m - a[0]) / (b[0] - a[0]));
      return out.fromArray(a[1]).lerp(new V3().fromArray(b[1]), k);
    }
    return out.fromArray(arr[arr.length - 1][1]);
  }
  function kfCol(arr, m, out) {
    if (m <= arr[0][0]) return out.copy(arr[0][1]);
    for (var i = 1; i < arr.length; i++) if (m <= arr[i][0]) { var a = arr[i - 1], b = arr[i]; return out.copy(a[1]).lerp(b[1], sm((m - a[0]) / (b[0] - a[0]))); }
    return out.copy(arr[arr.length - 1][1]);
  }
  function winAlpha(w, m) { return sm((m - w[0]) / 0.2) * sm((w[1] - m) / 0.2); }

